Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

$base = "C:\Users\ADMINI~1\AppData\Local\Temp\claude\C--Users-Administrator\24e2047e-3c4f-4c8a-9dc1-171d2a76cc25\scratchpad\docxbuild"
$dst  = "C:\Users\Administrator\配車業務デジタル化のご提案_KitamuraSG様.docx"
if (Test-Path $dst) { Remove-Item $dst -Force }

$entries = @(
  @{ File = "$base\[Content_Types].xml";              Name = "[Content_Types].xml" },
  @{ File = "$base\_rels\.rels";                       Name = "_rels/.rels" },
  @{ File = "$base\word\document.xml";                 Name = "word/document.xml" },
  @{ File = "$base\word\styles.xml";                   Name = "word/styles.xml" },
  @{ File = "$base\word\_rels\document.xml.rels";      Name = "word/_rels/document.xml.rels" }
)

$zip = [System.IO.Compression.ZipFile]::Open($dst, [System.IO.Compression.ZipArchiveMode]::Create)
try {
  foreach ($e in $entries) {
    $entry  = $zip.CreateEntry($e.Name, [System.IO.Compression.CompressionLevel]::Optimal)
    $stream = $entry.Open()
    $bytes  = [System.IO.File]::ReadAllBytes($e.File)
    $stream.Write($bytes, 0, $bytes.Length)
    $stream.Close()
  }
} finally {
  $zip.Dispose()
}

if (Test-Path $dst) {
  $fi = Get-Item $dst
  "OK: $($fi.FullName)"
  "Size: $($fi.Length) bytes"
} else { "FAILED" }

Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$dst = "C:\Users\Administrator\配車業務デジタル化のご提案_KitamuraSG様.docx"
$zip = [System.IO.Compression.ZipFile]::OpenRead($dst)
try {
  "== Entries =="
  $zip.Entries | ForEach-Object { $_.FullName }
  ""
  "== XML well-formedness check =="
  foreach ($name in @("word/document.xml","word/styles.xml","[Content_Types].xml","_rels/.rels","word/_rels/document.xml.rels")) {
    $entry = $zip.GetEntry($name)
    $sr = New-Object System.IO.StreamReader($entry.Open(), [System.Text.Encoding]::UTF8)
    $content = $sr.ReadToEnd(); $sr.Close()
    try { [xml]$x = $content; "OK  $name" } catch { "BAD $name -> $($_.Exception.Message)" }
  }
} finally { $zip.Dispose() }

